targets.query:
import "array"
import "regexp"
import "strings"

// Same helper as the traffic dashboards: the CIDR box becomes an anchored prefix
// regex, the only form InfluxDB pushes down to storage. Prefix lengths other
// than /8, /16, /24 and /32 round DOWN to the enclosing octet boundary.
cidrPrefix = (cidr) => {
    p = strings.split(v: cidr, t: "/")
    bits = if length(arr: p) > 1 then int(v: p[1]) else 32
    o = strings.split(v: p[0], t: ".")

    return
        if bits <= 8 then "^" + o[0] + "\\."
        else if bits <= 16 then "^" + o[0] + "\\." + o[1] + "\\."
        else if bits <= 24 then "^" + o[0] + "\\." + o[1] + "\\." + o[2] + "\\."
        else "^" + o[0] + "\\." + o[1] + "\\." + o[2] + "\\." + o[3] + "$"
}

cidrRe = if "${cidr}" == "" then /.*/ else regexp.compile(v: cidrPrefix(cidr: "${cidr}"))
// The MAC box is a prefix, so a whole vendor block (48:a9:8a) works too.
macRe = if "${mac}" == "" then /.*/
    else regexp.compile(v: "^" + regexp.quoteMeta(v: strings.toLower(v: strings.trimSpace(v: "${mac}"))))

// ~96 buckets whatever the range, floored at the service's 60s window, below
// which there is nothing finer to show; labelled with the window START, so
// zooming onto a bar selects the minutes that drew it.
spanNs = int(v: v.timeRangeStop) - int(v: v.timeRangeStart)
everyNs = if spanNs / 96 < 60000000000 then 60000000000 else spanNs / 96
every = duration(v: everyNs)

from(bucket: "network_traffic")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "arp_alert" and r._field == "count")
  |> filter(fn: (r) => r.severity =~ /^${severity:regex}$/)
  |> filter(fn: (r) => r.ip =~ cidrRe)
  |> aggregateWindow(every: every, fn: sum, timeSrc: "_start", createEmpty: false)
  |> group(columns: ["severity", "severity_name"])
  |> aggregateWindow(every: every, fn: sum, timeSrc: "_start", createEmpty: false)
  |> keep(columns: ["_time", "_value", "severity", "severity_name"])

// ~96 buckets whatever the range, floored at the service's 60s window, below
// which there is nothing finer to show; labelled with the window START, so
// zooming onto a bar selects the minutes that drew it.
spanNs = int(v: v.timeRangeStop) - int(v: v.timeRangeStart)
everyNs = if spanNs / 96 < 60000000000 then 60000000000 else spanNs / 96
every = duration(v: everyNs)

from(bucket: "network_traffic")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "arp_watch")
  |> filter(fn: (r) => r._field == "requests" or r._field == "replies" or r._field == "gratuitous"
      or r._field == "unsolicited" or r._field == "probes" or r._field == "capture_drops")
  |> aggregateWindow(every: every, fn: sum, timeSrc: "_start", createEmpty: false)
  |> keep(columns: ["_time", "_value", "_field"])
